/**
 * Point taps: how a viewport point an executor names is routed onto the
 * tree, and how the result reads back. A point goes to the engine as a bare
 * point, where the model aimed, and the trace keeps it inside the node under
 * it; an engine that taps listed nodes only gets the enabled control
 * containing the point, tapped by its id. Coordinates read off a screenshot
 * are scaled into the observation's CSS pixels first.
 */
import { clamp, clampToViewport, containsPoint } from '../internal/geometry.js';
import { INTERACTIVE_ROLES } from './observation.js';
/**
 * Scales a point read off a screenshot into the observation's CSS pixels and
 * clamps it to the viewport. `pixels.scale` is image pixels per CSS pixel
 * (3 on a device screenshot, 1 on a CSS-scale capture); the observation's
 * own `viewport.scale` is not consulted, because a device engine reports its
 * geometry in logical points regardless of the image.
 */
export function imagePointToViewport(point, pixels, viewport) {
    const scale = pixels.scale > 0 ? pixels.scale : 1;
    return clampToViewport({
        x: clamp(point.x, 0, Math.max(0, pixels.width - 1)) / scale,
        y: clamp(point.y, 0, Math.max(0, pixels.height - 1)) / scale,
    }, viewport);
}
/**
 * Finds what the newest observation lists at a viewport point. Only an
 * enabled interactive role counts as the control: tapping a node taps its
 * center, which is what the caller asked for only when the node is the
 * control itself, not a paragraph or region that happens to contain the
 * point.
 */
export function hitTest(observation, point) {
    if (observation.kind === 'pixels')
        return { control: undefined, under: undefined };
    return {
        control: innermostAt(observation, point, (node) => INTERACTIVE_ROLES.has(node.role ?? '') && node.states?.disabled !== true),
        under: innermostAt(observation, point),
    };
}
/**
 * The innermost listed node whose box contains the point, among those
 * `accept` admits: deepest in the tree, then the smallest box. Hidden nodes
 * and nodes without a box are skipped. Every box is in the top-level
 * viewport's CSS pixels, nested documents included (`RedactedNode.rect`), so
 * a node inside an iframe is found like any other.
 */
function innermostAt(observation, point, accept = () => true) {
    let best;
    for (const node of observation.nodes.values()) {
        const rect = node.rect;
        if (rect === undefined || rect.width <= 0 || rect.height <= 0)
            continue;
        if (node.states?.hidden === true || !containsPoint(rect, point) || !accept(node))
            continue;
        const candidate = { node, depth: depthOf(node.ref.id, observation.parents), area: rect.width * rect.height };
        if (inner(candidate, best))
            best = candidate;
    }
    return best?.node;
}
function inner(candidate, best) {
    if (best === undefined)
        return true;
    if (candidate.depth !== best.depth)
        return candidate.depth > best.depth;
    return candidate.area < best.area;
}
function depthOf(id, parents) {
    let depth = 0;
    for (let cursor = parents.get(id); cursor !== undefined; cursor = parents.get(cursor))
        depth += 1;
    return depth;
}
/** The observation's own line for a node, as the model already reads it; the id alone when the line was cut. */
export function nodeLine(observation, id) {
    for (const line of observation.text.split('\n')) {
        const trimmed = line.trimStart();
        if (trimmed.startsWith(`#${id} `) || trimmed === `#${id}`)
            return trimmed;
    }
    return `#${id}`;
}
/**
 * The point verbs: the node verb each resolves onto on an engine without
 * the bare-point kind, and how each reads back to the model. The one place
 * the pairing lives; the tools, the dispatcher, and the prose read it.
 */
export const POINT_VERBS = {
    tapAt: { node: 'tap', did: 'Tapped' },
    hoverAt: { node: 'hover', did: 'Hovered over' },
};
/**
 * What one point action did, for the model that named the point: the
 * control it acted on by id, the control it acted inside as a bare point,
 * or the bare point on nothing listed.
 */
export function describePointAction(input) {
    const { did } = POINT_VERBS[input.verb];
    const at = `(${String(input.point.x)}, ${String(input.point.y)})`;
    if (input.control !== undefined) {
        if (input.byId)
            return `${did} ${describeNode(input, input.control)}, the control at ${at}.`;
        return `${did} the point ${at} inside ${describeNode(input, input.control)}.`;
    }
    const under = input.under === undefined ? '' : ` (under it: ${describeNode(input, input.under)})`;
    return `${did} the point ${at}; no listed control is there${under}.`;
}
/**
 * What one point drag did, for the model that named the points: the two
 * controls it joined by id, or the bare points with what each sits on.
 */
export function describePointDrag(input) {
    const at = (point) => `(${String(point.x)}, ${String(point.y)})`;
    if (input.byId && input.source !== undefined && input.destination !== undefined) {
        return `Dragged ${describeNode(input, input.source)}, the control at ${at(input.from)}, onto ${describeNode(input, input.destination)}, the control at ${at(input.to)}.`;
    }
    const end = (point, control, under) => {
        if (control !== undefined)
            return `the point ${at(point)} inside ${describeNode(input, control)}`;
        return `the point ${at(point)}${under === undefined ? '' : ` (under it: ${describeNode(input, under)})`}`;
    };
    const neither = input.source === undefined && input.destination === undefined ? '; no listed control is at either end' : '';
    return `Dragged from ${end(input.from, input.source, input.fromUnder)} to ${end(input.to, input.destination, input.toUnder)}${neither}.`;
}
/** What one hit test found, for the model that named the point. */
export function describePointHit(input) {
    const at = `(${String(input.point.x)}, ${String(input.point.y)})`;
    if (input.control !== undefined)
        return `${describeNode(input, input.control)}, the control at ${at}`;
    if (input.under !== undefined)
        return `no control is listed at ${at}; under it: ${describeNode(input, input.under)}`;
    return `nothing the screen lists is at ${at}`;
}
/** A node as prose: its observation line, which the model holds. */
function describeNode(prose, node) {
    return nodeLine(prose.observation, node.ref.id);
}
